  const ul = (arr, empty) => arr.length ? '<ul style="padding-left:18px;margin:6px 0 16px">' + arr.map((x) => '<li style="margin:4px 0">' + esc(x) + '</li>').join('') + '</ul>' : '<p style="margin:6px 0 16px;color:#666">' + empty + '</p>';
  const h = (t) => '<p style="margin:18px 0 0"><b style="letter-spacing:.08em;text-transform:uppercase;font-size:12px;color:#2F6BFF">' + t + '</b></p>';
