  const s = await resend(env, { from: env.FROM_EMAIL || 'Northlight Studio <onboarding@resend.dev>', to: [env.TO_EMAIL], subject: 'Mid-month check: ' + money(owedTotal) + ' owed, ' + contracts.length + ' contract' + (contracts.length === 1 ? '' : 's') + ' to close out', text, html });
