async function invoiceRows(env, ids, email) {
  for (const col of ['invoice_no TEXT', 'invoice_date TEXT']) { try { await env.DB.prepare('ALTER TABLE clients ADD COLUMN ' + col).run(); } catch (e) {} }
  const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York' }).format(new Date());
  const out = [];
  for (const id of ids) {
    const c = await env.DB.prepare('SELECT * FROM clients WHERE id = ?').bind(id).first();
    if (!c || c.status === 'Inquiry' || c.status === 'Quoted') continue;
    if (email) {
      if (String(c.email || '').toLowerCase() !== email || +c.doe) continue;
      if (!(c.signed_at || c.contract_signed || c.balance_paid)) continue;
    }
    if (!c.invoice_no) {
      const mx = await env.DB.prepare("SELECT COALESCE(MAX(CAST(SUBSTR(invoice_no, 5) AS INTEGER)), 0) AS n FROM clients WHERE invoice_no LIKE 'NLS-%'").first();
      const no = 'NLS-' + String(((mx && mx.n) || 0) + 1).padStart(4, '0');
      await env.DB.prepare('UPDATE clients SET invoice_no = ?, invoice_date = ? WHERE id = ?').bind(no, today, c.id).run();
      c.invoice_no = no; c.invoice_date = today;
    }
    out.push(c);
  }
  return out;
}
function invoiceResponse(rows) {
  const fn = rows.length === 1 ? 'northlight-studio-Invoice-' + rows[0].invoice_no + '.pdf' : 'northlight-studio-Invoices.pdf';
  return new Response(invoicePdf(rows), { status: 200, headers: { 'Content-Type': 'application/pdf', 'Content-Disposition': 'attachment; filename="' + fn + '"', 'Cache-Control': 'private, no-store' } });
}
async function contractPdf(c) {
  if (!c || !c.contract_body || !c.signed_at) return new Response('There is no signed contract here yet.', { status: 404 });
  const dig = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(c.contract_body));
  const h = Array.from(new Uint8Array(dig)).map((x) => x.toString(16).padStart(2, '0')).join('');
  const sig = ['ELECTRONIC SIGNATURE', 'Signed by: ' + c.signed_name, 'Signed on (UTC): ' + c.signed_at, 'IP address: ' + (c.signed_ip || 'not recorded'), 'Document fingerprint (SHA-256): ' + c.signed_hash, 'Fingerprint matches the text above: ' + (h === c.signed_hash ? 'yes' : 'no')];
  const pdf = pdfBuild('Northlight Studio | Signed contract', c.contract_body, sig);
  const nm = String(c.name || 'client').replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'client';
  return new Response(pdf, { status: 200, headers: { 'Content-Type': 'application/pdf', 'Content-Disposition': 'attachment; filename="northlight-studio-Contract-' + nm + '.pdf"', 'Cache-Control': 'private, no-store' } });
}

